const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
fs.mkdirSync(STATE, { recursive: true });
const token = ENV('TELEGRAM_BOT_TOKEN');
const tg = (method, body) => this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + token + '/' + method,
  body: body || {},
  json: true
});

// Fail fast on a missing webhook secret: registering with
// secret_token=undefined leaves every delivery UNSIGNED while Handle
// TG Update fails closed on a missing signature - moderation goes
// silently dead while this node reports 'webhook registered'. Same
// guard as tools/tg_webhook_setup.sh's `:?` check. The env is passed
// through docker-compose.yml from ../ENV.
const hookSecret = ENV('TG_WEBHOOK_SECRET');
if (!hookSecret) {
  throw new Error('TG_WEBHOOK_SECRET is not set - refusing to register ' +
    'an unsigned webhook (the tg-moderation gate would drop every ' +
    'update). Generate one (openssl rand -hex 32), add it to ../ENV, ' +
    'recreate the n8n container, then re-run this workflow.');
}

// 1. resolve the operator chat_id. PINNED config wins over discovery:
// TELEGRAM_CHAT_ID env first, then the tg.json written by a previous
// run. The getUpdates self-heal runs only when neither exists AND no
// webhook is registered yet - and it pins whoever messaged the bot
// LAST, so a third party writing between the operator's /start and
// this run would become 'operator' (see the multi-chat warning below).
// sp-tg-moderation never learns chat_id from untrusted updates.
let chatId = ENV('TELEGRAM_CHAT_ID') || null;
let chatSource = chatId ? 'TELEGRAM_CHAT_ID env' : null;
if (!chatId) {
  try {
    chatId = JSON.parse(fs.readFileSync(STATE + '/tg.json', 'utf8')).chat_id;
    chatSource = chatId ? 'tg.json' : null;
  } catch (e) {}
}
const info = await tg('getWebhookInfo');
const hookAlreadySet = !!(info.result && info.result.url);
let updateChats = 0;
if (!chatId && !hookAlreadySet) {
  const r = await tg('getUpdates', { limit: 50 });
  const seen = {};
  for (const u of (r.result || [])) {
    const m = u.message || u.edited_message || (u.callback_query && u.callback_query.message);
    if (m && m.chat && m.chat.id) {
      seen[String(m.chat.id)] = true;
      chatId = m.chat.id;
    }
  }
  updateChats = Object.keys(seen).length;
  if (chatId) chatSource = 'getUpdates last sender';
}
if (chatId) {
  fs.writeFileSync(STATE + '/tg.json', JSON.stringify({ chat_id: chatId, saved_at: new Date().toISOString() }));
}

// 2. point the bot webhook at the moderation callback endpoint
const base = ENV('WEBHOOK_URL').replace(/\/+$/, '');
let hook = null;
if (chatId) {
  hook = await tg('setWebhook', {
    url: base + '/webhook/tg-moderation',
    allowed_updates: ['message', 'callback_query'],
    // authenticity: Telegram signs every delivery with this token
    // (X-Telegram-Bot-Api-Secret-Token header), which Handle TG
    // Update verifies before touching any update. The same
    // registration lives in tools/tg_webhook_setup.sh. Required -
    // the guard above aborts the run when the env is unset.
    secret_token: hookSecret
  });
}

let note;
if (chatId && hook && hook.ok) {
  note = 'chat_id saved (' + chatSource + '), webhook registered with secret_token';
} else if (hookAlreadySet && !chatId) {
  note = 'webhook already registered; set TELEGRAM_CHAT_ID or keep tg.json as the pinned chat';
} else {
  note = 'no updates found - send /start to @shared_person_bot from your account, then run this workflow again';
}
// the getUpdates fallback pins whoever messaged the bot LAST - a
// third party between the operator's /start and this run becomes
// 'operator'. Warn loudly when several distinct chats wrote in so the
// operator verifies tg.json instead of trusting a hijack.
if (updateChats > 1) {
  note += ' | WARNING: getUpdates saw ' + updateChats + ' distinct ' +
    'chats - the LAST sender became tg.json. Verify it is yours, or ' +
    'pin TELEGRAM_CHAT_ID in ENV and re-run';
}
return [{ json: { ok: !!chatId, chat_id: chatId, chat_source: chatSource, webhook_set: !!(hook && hook.ok), note: note } }];
